import { db, storage, json, error, type RouterContext } from '@appdeploy/sdk';

export const BACKUP_TABLES = [
  'community_posts', 'free_public_run_leases', 'free_public_source_reads', 'free_public_source_runs',
  'growth_advertiser_leads', 'growth_campaigns', 'growth_social_queue', 'hard_exa_cursor', 'motor3_web_cursor',
  'notification_dispatch_log', 'notification_dispatch_state', 'notification_preferences',
  'public_feed_build_state', 'public_feed_changes', 'public_feed_control', 'public_feed_identity_policy',
  'public_feed_manifests', 'public_feed_versions', 'radar_candidates', 'radar_document_revalidation_receipts',
  'radar_document_revalidation_state', 'radar_empty_recovery', 'radar_enrichment_cursor',
  'radar_external_pull_state', 'radar_jobs', 'radar_live_tests', 'radar_local_contact_rechecks',
  'radar_meta', 'radar_social_recovery_cursor', 'radar_sources', 'radar_verification_cursor',
  'security_request_limits', 'social_capture_runs', 'social_notice_evidence', 'source_audits', 'source_meta', 'source_scan_state'
];

export function backupTableAllowed(table: unknown): table is string {
  return typeof table === 'string' && (BACKUP_TABLES.includes(table) || /^radar_external_[a-f0-9]{32}$/.test(table) || /^public_feed_page_[0-9]{1,8}$/.test(table));
}

function privateResponse(data: unknown) {
  const response = json(data);
  response.headers = { ...response.headers, 'Cache-Control': 'no-store, private', 'Vary': 'Authorization', 'X-Content-Type-Options': 'nosniff' };
  return response;
}

// Mounted only after requireAuth + requireAdminEmailAllowlist in index.ts.
// Reads one bounded page or one object. No writes, retries or growing-table drain.
export async function adminBackupPage(ctx: RouterContext) {
  const body = (ctx.body || {}) as Record<string, unknown>;
  if (body.kind === 'scope') return privateResponse({ tables: BACKUP_TABLES, revision: 'application-backup-v1', consistency: 'rolling_non_atomic', fullPlatformBackup: false });
  const cursor = body.cursor;
  if (cursor !== undefined && cursor !== null && (typeof cursor !== 'string' || cursor.length > 16000)) return error('Cursor inválido.', 400);
  const options = { limit: 5, ...(typeof cursor === 'string' && cursor ? { nextToken: cursor } : {}) };
  if (body.kind === 'table') {
    if (!backupTableAllowed(body.table)) return error('Tabla fuera del ámbito autorizado.', 400);
    const page = await db.list(body.table, options);
    if (Buffer.byteLength(JSON.stringify(page), 'utf8') > 1500000) return error('Página demasiado grande para una descarga segura.', 413);
    return privateResponse({ kind: 'table', table: body.table, items: page.items, nextToken: page.nextToken || null });
  }
  if (body.kind === 'storage') {
    const page = await storage.list({ ...options, limit: 5 });
    return privateResponse({ kind: 'storage', paths: page.paths, nextToken: page.nextToken || null });
  }
  if (body.kind === 'file') {
    const path = body.path;
    if (typeof path !== 'string' || !path || path.length > 1024 || path.startsWith('/') || path.includes('\\') || path.split('/').some(part => !part || part === '..' || part === '.')) return error('Ruta inválida.', 400);
    const [file] = await storage.read([path]);
    if (!file || file.path !== path || file.content === null) return error('El archivo no está disponible. La copia está incompleta.', 409);
    if (Buffer.byteLength(file.content, 'utf8') > 1500000) return error('Archivo demasiado grande para este exportador. Requiere respaldo de plataforma.', 413);
    return privateResponse({ kind: 'file', path, content: file.content });
  }
  return error('Operación de respaldo inválida.', 400);
}

const encoder = new TextEncoder();
const decoder = new TextDecoder();
const FORMAT = 'trabajo-cerca.encrypted-backup.v1';
const ITERATIONS = 310000;
export type CipherPart = { iv: string; content: string };
export type BackupEnvelope = { format: string; id: string; salt: string; iterations: number; parts: CipherPart[] };

function base64(bytes: Uint8Array): string {
  let text = '';
  for (let offset = 0; offset < bytes.length; offset += 8192) text += String.fromCharCode(...bytes.subarray(offset, offset + 8192));
  return btoa(text);
}
function bytes(text: string): Uint8Array {
  return Uint8Array.from(atob(text), character => character.charCodeAt(0));
}
async function keyFor(password: string, salt: Uint8Array) {
  const input = await crypto.subtle.importKey('raw', encoder.encode(password), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: salt.buffer as ArrayBuffer, iterations: ITERATIONS, hash: 'SHA-256' }, input, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
}
export async function beginEncryptedBackup(password: string) {
  if (password.length < 12) throw new Error('Usa una contraseña de al menos 12 caracteres.');
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const envelope: BackupEnvelope = { format: FORMAT, id: crypto.randomUUID(), salt: base64(salt), iterations: ITERATIONS, parts: [] };
  return { envelope, key: await keyFor(password, salt) };
}
export async function appendEncrypted(envelope: BackupEnvelope, key: CryptoKey, value: unknown) {
  if (envelope.parts.length >= 2000) throw new Error('Límite de páginas alcanzado. La copia no está completa.');
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const additionalData = encoder.encode(FORMAT + ':' + envelope.id + ':' + envelope.parts.length);
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData }, key, encoder.encode(JSON.stringify(value)));
  envelope.parts.push({ iv: base64(iv), content: base64(new Uint8Array(ciphertext)) });
}
export async function verifyEncryptedBackup(text: string, password: string) {
  if (text.length > 60000000) throw new Error('El archivo supera el límite de comprobación.');
  const envelope = JSON.parse(text) as BackupEnvelope;
  if (envelope.format !== FORMAT || envelope.iterations !== ITERATIONS || typeof envelope.id !== 'string' || envelope.id.length > 100 || !Array.isArray(envelope.parts) || envelope.parts.length < 1 || envelope.parts.length > 2000) throw new Error('Formato de respaldo no válido.');
  const salt = bytes(envelope.salt);
  if (salt.length !== 16) throw new Error('Sal de cifrado inválida.');
  const key = await keyFor(password, salt);
  const tables = new Map<string, Set<string>>();
  const paths = new Set<string>();
  let manifest: { kind: string; complete: boolean; parts: number; tables: Array<{ table: string; count: number }>; files: number } | null = null;
  for (let index = 0; index < envelope.parts.length; index++) {
    const part = envelope.parts[index];
    const iv = bytes(part.iv);
    if (iv.length !== 12) throw new Error('Bloque cifrado inválido.');
    const clear = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: iv.buffer as ArrayBuffer, additionalData: encoder.encode(FORMAT + ':' + envelope.id + ':' + index) }, key, bytes(part.content).buffer as ArrayBuffer);
    const value = JSON.parse(decoder.decode(clear));
    if (value.kind === 'manifest') {
      if (index !== envelope.parts.length - 1 || manifest) throw new Error('Orden del manifiesto inválido.');
      manifest = value;
    } else if (value.kind === 'table') {
      if (typeof value.table !== 'string' || !Array.isArray(value.items)) throw new Error('Página inválida.');
      const ids = tables.get(value.table) || new Set<string>();
      for (const row of value.items) {
        if (typeof row.id !== 'string' || !row.id || ids.has(row.id)) throw new Error('ID duplicado o ausente. Repite el respaldo.');
        ids.add(row.id);
      }
      tables.set(value.table, ids);
    } else if (value.kind === 'file') {
      if (typeof value.path !== 'string' || typeof value.content !== 'string' || paths.has(value.path)) throw new Error('Archivo duplicado o inválido.');
      paths.add(value.path);
    } else throw new Error('Bloque desconocido.');
  }
  if (!manifest?.complete || manifest.parts !== envelope.parts.length - 1 || !Array.isArray(manifest.tables) || manifest.tables.length !== tables.size || manifest.files !== paths.size) throw new Error('Respaldo incompleto.');
  const listed = new Set<string>();
  for (const entry of manifest.tables) {
    if (listed.has(entry.table) || !tables.has(entry.table) || tables.get(entry.table)!.size !== entry.count) throw new Error('Inventario de tablas inconsistente.');
    listed.add(entry.table);
  }
  return { tables: tables.size, records: [...tables.values()].reduce((sum, ids) => sum + ids.size, 0), files: paths.size, platformRestoreTested: false };
}

import { useRef, useState } from 'react';
import { api } from '@appdeploy/client';
import { appendEncrypted, beginEncryptedBackup, verifyEncryptedBackup, type BackupEnvelope } from './backup-crypto';
import './backup-panel.css';

type Page = { kind: string; table?: string; items?: Array<Record<string, unknown> & { id: string }>; paths?: string[]; path?: string; content?: string; nextToken?: string | null };
const APP_ID = 'trabajo-cerca-laboratorio-3ojgro';
const dynamicTable = /^(radar_external_[a-f0-9]{32}|public_feed_page_[0-9]{1,8})$/;

function discoverTables(value: unknown, tables: string[], seen: Set<string>) {
  if (typeof value === 'string' && dynamicTable.test(value) && !seen.has(value)) { seen.add(value); tables.push(value); }
  else if (Array.isArray(value)) value.forEach(item => discoverTables(item, tables, seen));
  else if (value && typeof value === 'object') Object.values(value).forEach(item => discoverTables(item, tables, seen));
}

export function BackupPanel() {
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('Crea una copia cifrada y guárdala fuera de este dispositivo.');
  const [download, setDownload] = useState<{ text: string; complete: boolean } | null>(null);
  const cancelled = useRef(false);

  async function createBackup() {
    if (password.length < 12 || password !== confirmation) { setMessage('Usa al menos 12 caracteres y repite la misma contraseña.'); return; }
    setBusy(true); setDownload(null); cancelled.current = false;
    let envelope: BackupEnvelope | null = null;
    try {
      const startedAt = new Date().toISOString();
      const encrypted = await beginEncryptedBackup(password);
      envelope = encrypted.envelope;
      let calls = 0;
      let encryptedBytes = 0;
      const add = async (value: unknown) => {
        await appendEncrypted(encrypted.envelope, encrypted.key, value);
        encryptedBytes += encrypted.envelope.parts[encrypted.envelope.parts.length - 1].content.length;
        if (encryptedBytes > 45000000) throw new Error('backup_limit');
      };
      const read = async (body: unknown): Promise<Page> => {
        if (cancelled.current || ++calls > 1000 || Date.now() - Date.parse(startedAt) > 600000) throw new Error('backup_limit');
        const response = await api.post('/api/admin/backup/page', body);
        return response.data;
      };
      const scope = await api.post('/api/admin/backup/page', { kind: 'scope' });
      if (!Array.isArray(scope.data.tables) || !scope.data.tables.length) throw new Error('invalid_scope');
      const tables: string[] = [...scope.data.tables];
      const known = new Set(tables);
      const counts: Array<{ table: string; count: number }> = [];
      for (let index = 0; index < tables.length; index++) {
        if (tables.length > 500) throw new Error('backup_limit');
        const table = tables[index];
        const ids = new Set<string>();
        const tokens = new Set<string>();
        let cursor: string | null = null;
        do {
          const page = await read({ kind: 'table', table, cursor });
          if (page.kind !== 'table' || page.table !== table || !Array.isArray(page.items)) throw new Error('invalid_page');
          for (const row of page.items) {
            if (typeof row.id !== 'string' || ids.has(row.id)) throw new Error('duplicate_id');
            ids.add(row.id);
          }
          discoverTables(page.items, tables, known);
          await add({ kind: 'table', table, items: page.items });
          cursor = page.nextToken || null;
          if (cursor && tokens.has(cursor)) throw new Error('pagination_loop');
          if (cursor) tokens.add(cursor);
          setMessage(`Copiando datos: ${index + 1} de ${tables.length} tablas; ${ids.size} registros en la tabla actual.`);
        } while (cursor);
        counts.push({ table, count: ids.size });
      }
      const paths = new Set<string>();
      const tokens = new Set<string>();
      let cursor: string | null = null;
      do {
        const page = await read({ kind: 'storage', cursor });
        if (!Array.isArray(page.paths)) throw new Error('invalid_storage_page');
        for (const path of page.paths) {
          if (paths.has(path)) throw new Error('duplicate_path');
          paths.add(path);
          const file = await read({ kind: 'file', path });
          if (file.kind !== 'file' || file.path !== path || typeof file.content !== 'string') throw new Error('missing_file');
          await add({ kind: 'file', path, content: file.content });
          setMessage(`Copiando archivos: ${paths.size}.`);
        }
        cursor = page.nextToken || null;
        if (cursor && tokens.has(cursor)) throw new Error('pagination_loop');
        if (cursor) tokens.add(cursor);
      } while (cursor);
      await add({ kind: 'manifest', complete: true, appId: APP_ID, revision: scope.data.revision, startedAt, finishedAt: new Date().toISOString(), consistency: 'rolling_non_atomic', fullPlatformBackup: false, dynamicCatalogueCertified: false, storageMetadataIncluded: false, tables: counts, files: paths.size, parts: encrypted.envelope.parts.length });
      const text = JSON.stringify(encrypted.envelope);
      const checked = await verifyEncryptedBackup(text, password);
      setDownload({ text, complete: true });
      setMessage(`Copia cifrada comprobada: ${checked.tables} tablas, ${checked.records} registros y ${checked.files} archivos. Descárgala ahora. Falta probar la restauración en una instancia aislada.`);
    } catch {
      if (envelope?.parts.length) setDownload({ text: JSON.stringify(envelope), complete: false });
      setMessage('La copia no se completó. Puede haberse alcanzado un límite o fallado una lectura. No se modificaron tus datos. Puedes conservar la copia parcial cifrada, pero no sirve como respaldo completo.');
    } finally { setBusy(false); }
  }

  function saveDownload() {
    if (!download) return;
    const url = URL.createObjectURL(new Blob([download.text], { type: 'application/json' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `trabajo-cerca-${download.complete ? 'copia' : 'PARCIAL'}-${new Date().toISOString().slice(0, 10)}.tcbackup`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  }

  async function verifyFile(file?: File) {
    if (!file) return;
    if (!password || file.size > 60000000) { setMessage('Ingresa la contraseña de esa copia y selecciona un archivo de menos de 60 MB.'); return; }
    setBusy(true);
    try {
      const result = await verifyEncryptedBackup(await file.text(), password);
      setMessage(`Archivo íntegro: ${result.tables} tablas, ${result.records} registros y ${result.files} archivos. Se comprobó localmente; no se restauró ni modificó la app.`);
    } catch { setMessage('No se pudo validar: contraseña incorrecta, archivo alterado o copia incompleta. No se modificó la app.'); }
    finally { setBusy(false); }
  }

  return (
    <section className='tcBackupPanel' aria-label='Respaldo cifrado'>
      <h3>Respaldo cifrado</h3>
      <p>La contraseña se queda en tu dispositivo. Guárdala por separado: no podremos recuperar una copia si la pierdes.</p>
      <div className='tcBackupFields'>
        <label>Contraseña del respaldo<input type='password' autoComplete='new-password' value={password} onChange={event => setPassword(event.target.value)} disabled={busy} minLength={12} /></label>
        <label>Repetir contraseña<input type='password' autoComplete='new-password' value={confirmation} onChange={event => setConfirmation(event.target.value)} disabled={busy} /></label>
      </div>
      <div className='tcBackupActions'>
        <button onClick={() => void createBackup()} disabled={busy || password.length < 12 || password !== confirmation}>Crear copia cifrada</button>
        {busy && <button onClick={() => { cancelled.current = true; }}>Cancelar copia</button>}
        {download && <button onClick={saveDownload} disabled={busy}>{download.complete ? 'Descargar copia cifrada' : 'Descargar copia parcial'}</button>}
        <label className='tcBackupFile'>Comprobar una copia<input type='file' accept='.tcbackup,application/json' disabled={busy} onChange={event => { const file = event.target.files?.[0]; event.target.value = ''; void verifyFile(file); }} /></label>
      </div>
      <p role='status' aria-live='polite'>{message}</p>
      <details><summary>Alcance y límites</summary><p>Incluye las tablas identificadas en el código, las tablas referenciadas durante la lectura y los archivos accesibles. No certifica tablas sin referencias ni incluye usuarios o secretos administrados por la plataforma, metadatos originales de archivos ni código fuente. Las lecturas ocurren mientras la app sigue funcionando: esta copia no es una instantánea atómica ni acredita una restauración completa. Los límites detienen la copia sin ocultar fallos.</p></details>
    </section>
  );
}

.tcBackupPanel { margin-top: 24px; border-top: 1px solid #dce5de; padding-top: 24px; }
.tcBackupPanel h3 { font-size: 18px; margin: 0; }
.tcBackupFields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 18px; }
.tcBackupFields label { display: flex; flex-direction: column; gap: 7px; font-size: 13px; color: #315344; }
.tcBackupFields input { min-width: 0; min-height: 46px; border: 1px solid #b8c9c2; border-radius: 10px; background: white; padding: 10px 12px; font-size: 16px; color: #163d32; }
.tcBackupActions { display: flex; flex-wrap: wrap; gap: 12px; margin: 18px 0 0; }
.tcBackupActions button, .tcBackupFile { border: 1px solid #b8c9c2; background: #fff; padding: 12px 16px; min-height: 46px; border-radius: 12px; font-size: 14px; }
.tcBackupActions button:first-child { background: #06231c; color: white; }
.tcBackupActions button:disabled { opacity: .5; cursor: not-allowed; }
.tcBackupFile { display: flex; flex-direction: column; gap: 8px; max-width: 100%; }
.tcBackupFile input { max-width: 100%; font-size: 12px; }
.tcBackupPanel summary { cursor: pointer; padding: 12px 0; font-size: 13px; }
.tcBackupPanel :focus-visible { outline: 3px solid #66a80f; outline-offset: 3px; }
@media (max-width: 600px) { .tcBackupFields { grid-template-columns: minmax(0, 1fr); } .tcBackupActions { flex-direction: column; } }

