      <p role='status' aria-live='polite'>{message}</p>
      <div className='tcAdminActions'>
      <button onClick={() => void verify(true)} disabled={busy}>Ingresar como administrador</button>
      <button onClick={() => void verify(false)} disabled={busy}>Verificar acceso</button>
      <button onClick={() => void signOut()} disabled={busy}>Cerrar sesión</button>
      </div>
      {allowed && <><p>Las operaciones manuales del radar continúan deshabilitadas.</p><BackupPanel /></>}
    </section>
  );
}

export function AdministratorShortcut() {
  const [allowed, setAllowed] = useState(false);
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    let active = true;
    let revision = 0;
    const check = async () => {
      const current = ++revision;
      setAllowed(false);
      const granted = await administratorPermission(auth.isSignedIn(), () => api.get('/api/admin/session'));
      if (active && revision === current) setAllowed(granted);
    };
    const visible = () => { if (document.visibilityState === 'visible') void check(); };
    void check();
    window.addEventListener('focus', check);
    document.addEventListener('visibilitychange', visible);
    return () => {
      active = false;
      revision += 1;
      window.removeEventListener('focus', check);
      document.removeEventListener('visibilitychange', visible);
    };
  }, []);
  async function openPanel() {
    setBusy(true);
    const granted = await administratorPermission(auth.isSignedIn(), () => api.get('/api/admin/session'));
    if (granted) {
      window.location.hash = 'operacion';
      window.location.reload();
    } else {
      setAllowed(false);
      setBusy(false);
    }
  }
  if (!allowed) return null;
  return <button className='tcAdminShortcut' disabled={busy} onClick={() => void openPanel()}>Administración</button>;
}
